    uint8_t failsafeRecoveryDelay;  // Delay after RTH finishes before attempting recovery (`failsafeConfig()->failsafe_recovery_delay`) | units: 0.1s
    uint16_t failsafeFWRollAngle;  // Fixed wing failsafe roll angle (`failsafeConfig()->failsafe_fw_roll_angle`) | units: deci-degrees
    uint16_t failsafeFWPitchAngle;  // Fixed wing failsafe pitch angle (`failsafeConfig()->failsafe_fw_pitch_angle`) | units: deci-degrees
    uint16_t failsafeFWYawRate;  // Fixed wing failsafe yaw rate (`failsafeConfig()->failsafe_fw_yaw_rate`) | units: deg/s
    uint16_t failsafeStickThreshold;  // Stick movement threshold to exit failsafe (`failsafeConfig()->failsafe_stick_motion_threshold`) | units: PWM units
    uint16_t failsafeMinDistance;  // Minimum distance from home for RTH failsafe (`failsafeConfig()->failsafe_min_distance`) | units: meters
    failsafeProcedure_e failsafeMinDistanceProc;  // Enum `failsafeProcedure_e` Failsafe procedure if below min distance ('failsafeConfig()->failsafe_min_distance_procedure') | units: Enum
