    uint8_t failsafeRecoveryDelay;  // Sets `failsafeConfigMutable()->failsafe_recovery_delay | units: 0.1s
    uint16_t failsafeFWRollAngle;  // Sets `failsafeConfigMutable()->failsafe_fw_roll_angle` (casted to `int16_t`) | units: deci-degrees
    uint16_t failsafeFWPitchAngle;  // Sets `failsafeConfigMutable()->failsafe_fw_pitch_angle` (casted to `int16_t`) | units: deci-degrees
    uint16_t failsafeFWYawRate;  // Sets `failsafeConfigMutable()->failsafe_fw_yaw_rate` (casted to `int16_t`) | units: deg/s
    uint16_t failsafeStickThreshold;  // Sets `failsafeConfigMutable()->failsafe_stick_motion_threshold | units: PWM units
    uint16_t failsafeMinDistance;  // Sets `failsafeConfigMutable()->failsafe_min_distance | units: meters
    failsafeProcedure_e failsafeMinDistanceProc;  // Enum `failsafeProcedure_e` Sets 'failsafeConfigMutable()->failsafe_min_distance_procedure' | units: Enum
