    int16_t magY;  // Raw magnetometer Y reading (`mag.magADC[Y]`). 0 if `USE_MAG` disabled | units: Raw units
    int16_t magZ;  // Raw magnetometer Z reading (`mag.magADC[Z]`). 0 if `USE_MAG` disabled | units: Raw units
